#!/bin/bash
# Railway start script for Happier (wraps the official happierdev/relay-server image).
#
# 1. As root: make the Railway volume (mounted root-owned) writable by the image's `happier` user, then re-run
#    this script as `happier`.
# 2. Owner bootstrap (first boot only): anonymous sign-up is closed on the public port from the very first boot.
#    The owner account is created from OWNER_SECRET_KEY (a 52-character base32 Happier secret key generated by
#    the template) by starting the server once on loopback with sign-up open, registering that key through
#    upstream's own key-challenge route (POST /v1/auth), and stopping it again. A marker on the volume records
#    which key was registered, so later boots skip this step.
# 3. Start the server on $PORT with AUTH_ANONYMOUS_SIGNUP_ENABLED=false (unless the deployer set it). The server
#    replaces this script (exec), so a crash exits non-zero and Railway's ON_FAILURE policy restarts it.
set -euo pipefail

log() { printf '[happier-railway] %s\n' "$*"; }
die() { log "ERROR: $*"; exit 1; }

DATA_DIR=${HAPPIER_SERVER_LIGHT_DATA_DIR:-/data}
SERVER=(run-server /opt/happier/server/happier-server)

if [ "$(id -u)" = "0" ]; then
  mkdir -p "$DATA_DIR"
  if [ "$(stat -c %U "$DATA_DIR")" != "happier" ] || [ -n "$(find "$DATA_DIR" ! -user happier -print -quit)" ]; then
    log "fixing ownership of $DATA_DIR"
    chown -R happier:happier "$DATA_DIR"
  fi
  exec setpriv --reuid=happier --regid=happier --init-groups env HOME=/home/happier "$0" "$@"
fi

[ -n "${DATABASE_URL:-}" ] || die "DATABASE_URL is empty: reference the Postgres service (\${{Postgres.DATABASE_URL}})"
[ -n "${HANDY_MASTER_SECRET:-}" ] || die "HANDY_MASTER_SECRET is empty: set a long random value and keep it stable"

# Public URLs: default to the Railway domain so QR codes, deep links and file URLs point at this service.
if [ -z "${HAPPIER_PUBLIC_SERVER_URL:-}" ] && [ -n "${RAILWAY_PUBLIC_DOMAIN:-}" ]; then
  export HAPPIER_PUBLIC_SERVER_URL="https://${RAILWAY_PUBLIC_DOMAIN}"
fi
if [ -n "${HAPPIER_PUBLIC_SERVER_URL:-}" ]; then
  export HAPPIER_WEBAPP_URL="${HAPPIER_WEBAPP_URL:-$HAPPIER_PUBLIC_SERVER_URL}"
  export PUBLIC_URL="${PUBLIC_URL:-$HAPPIER_PUBLIC_SERVER_URL}"
fi

# Decode a Happier secret key (base32, RFC 4648, dashes/spaces allowed, same normalisation as the app) to hex.
b32_to_hex() {
  local s=${1^^} alphabet=ABCDEFGHIJKLMNOPQRSTUVWXYZ234567 buf=0 bits=0 out='' c v i
  s=${s//0/O}; s=${s//1/I}; s=${s//8/B}; s=${s//9/G}
  s=${s//[^A-Z2-7]/}
  for ((i = 0; i < ${#s}; i++)); do
    c=${s:i:1}; v=${alphabet%%"$c"*}; v=${#v}
    buf=$(((buf << 5) | v)); bits=$((bits + 5))
    if ((bits >= 8)); then
      bits=$((bits - 8))
      out+=$(printf '%02x' $(((buf >> bits) & 255)))
    fi
    buf=$((buf & ((1 << bits) - 1)))
  done
  printf '%s' "$out"
}
hex_to_bin() { local h=$1 esc='' i; for ((i = 0; i < ${#h}; i += 2)); do esc+="\\x${h:i:2}"; done; printf '%b' "$esc"; }

bootstrap_owner() {
  local seed_hex tmp pub_b64 marker port pid ok=0 code i
  seed_hex=$(b32_to_hex "$OWNER_SECRET_KEY")
  [ ${#seed_hex} -ge 64 ] || die "OWNER_SECRET_KEY must be a Happier secret key (52 base32 characters)"
  seed_hex=${seed_hex:0:64}
  tmp=$(mktemp -d); chmod 700 "$tmp"
  # PKCS#8 DER wrapper for a raw Ed25519 seed (the app derives its signing key the same way: crypto_sign_seed_keypair).
  hex_to_bin "302e020100300506032b657004220420${seed_hex}" > "$tmp/key.der"
  pub_b64=$(openssl pkey -inform DER -in "$tmp/key.der" -pubout -outform DER | tail -c 32 | base64 -w0)
  marker="$DATA_DIR/.owner-$(printf '%s' "$pub_b64" | sha256sum | cut -c1-16)"
  if [ -f "$marker" ]; then
    rm -r "$tmp"; log "owner account already created"; return 0
  fi

  port=${HAPPIER_BOOTSTRAP_PORT:-3999}
  log "first boot: creating the owner account (server on 127.0.0.1:$port, migrations first)"
  HAPPIER_SERVER_HOST=127.0.0.1 PORT=$port AUTH_ANONYMOUS_SIGNUP_ENABLED=true "${SERVER[@]}" &
  pid=$!
  for i in $(seq 1 "${HAPPIER_BOOTSTRAP_WAIT_SECONDS:-240}"); do
    kill -0 "$pid" 2>/dev/null || { wait "$pid" || true; rm -r "$tmp"; die "server exited during first-boot setup"; }
    if curl -fsS -o /dev/null "http://127.0.0.1:$port/health"; then ok=1; break; fi
    sleep 1
  done
  [ "$ok" = 1 ] || { kill -KILL "$pid" 2>/dev/null || true; rm -r "$tmp"; die "server did not answer /health during first-boot setup"; }

  ok=0
  for i in 1 2 3 4 5; do
    head -c 32 /dev/urandom > "$tmp/challenge"
    openssl pkeyutl -sign -inkey "$tmp/key.der" -keyform DER -rawin -in "$tmp/challenge" -out "$tmp/sig"
    printf '{"publicKey":"%s","challenge":"%s","signature":"%s"}' \
      "$pub_b64" "$(base64 -w0 < "$tmp/challenge")" "$(base64 -w0 < "$tmp/sig")" > "$tmp/body.json"
    code=$(curl -sS -o "$tmp/resp" -w '%{http_code}' -H 'Content-Type: application/json' \
      --data-binary @"$tmp/body.json" "http://127.0.0.1:$port/v1/auth" || echo 000)
    if [ "$code" = 200 ] && grep -q '"success":true' "$tmp/resp"; then ok=1; break; fi
    log "owner registration answered HTTP $code; retrying"
    sleep 2
  done
  kill -TERM "$pid" 2>/dev/null || true
  for i in $(seq 1 10); do kill -0 "$pid" 2>/dev/null || break; sleep 1; done
  kill -KILL "$pid" 2>/dev/null || true
  wait "$pid" 2>/dev/null || true
  rm -r "$tmp"
  [ "$ok" = 1 ] || die "could not create the owner account"
  : > "$marker"
  log "owner account created; sign in with OWNER_SECRET_KEY (web app: Restore account > enter secret key)"
  export RUN_MIGRATIONS=0   # just applied
}

if [ -n "${OWNER_SECRET_KEY:-}" ]; then
  bootstrap_owner
else
  log "OWNER_SECRET_KEY is empty: no owner account is created"
fi

export AUTH_ANONYMOUS_SIGNUP_ENABLED="${AUTH_ANONYMOUS_SIGNUP_ENABLED:-false}"
log "starting Happier on port ${PORT:-3005} (anonymous sign-up: $AUTH_ANONYMOUS_SIGNUP_ENABLED)"
exec "${SERVER[@]}"
